        "split_newline_count": len(lines),
        "ends_with_newline": ends_with_newline,
        "blank_lines_in_split": blank,
        "repr": repr(s),
    }

return {
    "a": describe("data/a.txt", a),
    "b": describe("data/b.txt", b),
    "md": describe("data/ignore.md", md),
}

